import * as core from './ratio-bars-core.mjs';
import {ratioBarsCopy as copy} from './ratio-bars-content.mjs';
import {ratioBlocks,ratioBrace} from './ratio-bars-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>{try{return JSON.stringify(x,null,2);}catch{return 'Original data cannot be displayed here.';}};
const p=t=>`<p>${esc(t)}</p>`;
const button=(t,a='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${a}>${esc(t)}</button>`;
const msg=k=>copy[k]||k;
let visits=new WeakMap();
export function resetRatioBarsView(state){if(state&&typeof state==='object')visits.delete(state);else visits=new WeakMap();}
function visit(state,explorerId=''){let u=visits.get(state);if(!u||u.explorerId!==explorerId){u={explorerId,id:core.readRatioBars(state).source?.cases?.[0]?.id,helper:null,step:0};visits.set(state,u);}return u;}
const reference=(c,r)=>r==='whole'?'all bars together':c.ingredients.find(i=>i.id===r)?.label||'not placed';
const named=(c,plan)=>c.ingredients.map((i,n)=>`${plan.blocks[n]} ${i.label} ${plan.blocks[n]===1?'block':'blocks'}`).join(', ');
const recipe=c=>`${c.case.ratio.join(':')}, in this order: ${c.ingredients.map(i=>i.label).join(':')}.`;
const fact=c=>c.case.given.reference==='whole'?`Given: ${c.case.given.amount} model scoops altogether.`:`Given: ${c.case.given.amount} ${reference(c,c.case.given.reference)} model scoops.`;
const unsafe=c=>!c.draftReadable||!c.recordReadable||!c.supportReadable;
const sectionBad=v=>['drafts','observations','support'].some(k=>v[k]?.status!=='ready'||v[k]?.unreadable?.length);
function supplied(c){const i=c.case.initial;return `${p(`Supplied starting blocks: ${named(c,i)}`)}${p(i.unit===null?'Supplied value: not chosen':`Supplied value: ${i.unit} scoops in every block`)}${p(`Supplied reference: ${reference(c,i.reference)}`)}${c.case.guided.length?p('Guided example shown with this invitation'):''}`;}
function amounts(c,plan,checked=false){if(!c.modelSupported)return checked?p('Amounts are not recomputed for this earlier model. Its recorded counts, value, marker and results stay here.') :'';const a=core.ratioAmounts(c.case,plan);if(!a)return p('Value not chosen');return checked?`${p(`Computed shares for this checked model: ${c.ingredients.map((i,n)=>`${i.label} ${a.shares[n]} scoops`).join(', ')}.`)}${p(`Computed whole for this checked model: ${a.total} scoops.`)}`:`${c.ingredients.map((i,n)=>p(`${i.label}: ${plan.blocks[n]} × ${plan.unit} = ${a.shares[n]} scoops.`)).join('')}${p(`All bars together: ${a.total} scoops.`)}`;}
function model(c,plan){if(!c.modelSupported)return '';return `<div class="rb-picture">${plan.reference==='whole'?ratioBrace('all bars together'):''}${c.ingredients.map((i,n)=>`<div class="rb-picture-row"><strong>${esc(i.label)}: ${plan.blocks[n]} blocks</strong>${plan.reference===i.id?ratioBrace(i.label,plan.blocks[n]):''}${ratioBlocks(i,plan.blocks[n])}</div>`).join('')}</div>`;}
function checked(v,c,x,heading='Your checked model'){return `<section class="rb-checked"><h3 id="rb-checked-focus" tabindex="-1">${esc(heading)}</h3>${p(`This comparison used ${named(c,x)}, ${x.unit} scoops in every block, and your marker on ${reference(c,x.reference)}.`)}${model(c,x)}<div class="rb-statuses" role="status" aria-live="polite">${core.ratioFeedback(v.source,c.case,x).map(p).join('')}</div>${amounts(c,x,true)}</section>`;}
function bridge(v,c){return `<section class="rb-helper"><h2 id="rb-helper-focus" tabindex="-1">Back at the shade pots</h2><h3>Recipe from these bars</h3>${p(recipe(c))}${p(fact(c))}${!c.recordReadable?p(msg('Unreadable case')):c.latest?checked(v,c,c.latest,'Latest checked model'):c.plan?`<h3>Current model, not compared</h3>${model(c,c.plan)}${p(named(c,c.plan))}`:p(msg('Unreadable case'))}${p(msg('Bridge text'))}<a href="#studio/mixing">Visit the shade pots</a><a href="#studio/mixing/bars" data-rb-return>Return to equal blocks</a>${button('Back to my bars','data-rb-close')}</section>`;}
const helperLabels={whole:'Try a worked example',share:'A share is given',three:'Three parts',clue:'Clue',bridge:'Back at the shade pots'};
function helpers(v,u,c){if(!u.helper)return '';if(u.helper==='bridge')return bridge(v,c);if(u.helper==='clue')return `<section class="rb-helper"><h2 id="rb-helper-focus" tabindex="-1">Clue</h2>${p(c.case.clue)}${button('Close this idea','data-rb-close')}</section>`;const h=v.helpers[u.helper],s=h?.steps[u.step];if(!s)return p(msg('Missing helper'));const sc=core.ratioCaseView(v,s.caseId);return `<section class="rb-helper"><h2 id="rb-helper-focus" tabindex="-1">${esc(h.title)}</h2>${h.steps.some(s=>s.caseId===c.case.id)?p(msg('Own-invitation helper notice, when its frozen steps refer to the current case')):''}${model(sc,s.plan)}${p(s.text)}<nav>${button('Previous step',`data-rb-step="-1" ${u.step===0?'disabled':''}`)}${button('Next step',`data-rb-step="1" ${u.step===h.steps.length-1?'disabled':''}`)}</nav>${p(msg('Every helper footer'))}${button('Back to my bars','data-rb-close')}</section>`;}
function board(v,c){const plan=c.plan,editable=c.modelSupported&&c.draftReadable;if(!plan)return p(msg('Unreadable case'));const a=c.modelSupported?core.ratioAmounts(c.case,plan):null;return `<section class="rb-board"><h3>Your bars</h3>${c.suppliedStart?`<div class="rb-supplied">${p('Supplied starting blocks')}${p(plan.unit===null?'Supplied value: not chosen':`Supplied value: ${plan.unit} scoops in every block`)}${p(`Supplied reference: ${reference(c,plan.reference)}`)}</div>`:''}${c.modelSupported?`${plan.reference==='whole'?ratioBrace('all bars together'):''}${c.ingredients.map((i,n)=>`<section class="rb-row" data-rb-row="${esc(i.id)}"><div class="rb-row-heading"><h3>${esc(i.label)}: ${plan.blocks[n]} ${plan.blocks[n]===1?'block':'blocks'}</h3><div class="rb-row-actions">${button(`Add one ${i.label} block`,`data-rb-adjust="${esc(i.id)}" data-index="${n}" data-delta="1" ${!editable||plan.blocks[n]>=12?'disabled':''}`)}${button(`Take one ${i.label} block back`,`data-rb-adjust="${esc(i.id)}" data-index="${n}" data-delta="-1" ${!editable||plan.blocks[n]===0?'disabled':''}`)}</div></div>${plan.reference===i.id?ratioBrace(i.label,plan.blocks[n]):''}${ratioBlocks(i,plan.blocks[n])}<p class="rb-amount">${a?`${esc(i.label)}: ${plan.blocks[n]} × ${plan.unit} = ${a.shares[n]} scoops.`:'Value not chosen'}</p>${plan.blocks[n]===12?p(msg('Boundary12')):plan.blocks[n]===0?p(`There are no ${i.label} blocks to take back.`):''}</section>`).join('')}<div class="rb-settings"><label>Scoops in every block <select data-rb-unit ${!editable?'disabled':''}><option value="">Choose a value</option>${Array.from({length:20},(_,i)=>`<option value="${i+1}" ${plan.unit===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><fieldset><legend>Place the given-amount brace</legend>${[{id:'whole',label:'All bars together'},...c.ingredients].map(i=>`<label><input type="radio" name="rb-reference" data-rb-reference="${esc(i.id)}" value="${esc(i.id)}" ${plan.reference===i.id?'checked':''} ${!editable?'disabled':''}>${esc(i.label)}</label>`).join('')}</fieldset></div>${button('Compare',`data-rb-compare ${!editable||!c.recordReadable||!c.supportReadable||!v.teachingReadable?'disabled':''}`,true)}${p(`${plan.blocks.reduce((a,b)=>a+b,0)} ${plan.blocks.reduce((a,b)=>a+b,0)===1?'block':'blocks'} in all`)}${plan.unit!==null?p(`Every block stands for ${plan.unit} model ${plan.unit===1?'scoop':'scoops'}.`):''}${p(a?`All bars together: ${a.total} scoops.`:'Value not chosen')}${p(plan.reference?`Your reference marker: ${reference(c,plan.reference)}. Amount under your marker: ${a?`${a.markerAmount} scoops`:'value not chosen'}.`:'Given-amount brace not placed')}`:`${p(named(c,plan))}${p(`Scoops in every block: ${plan.unit??'not chosen'}. Reference marker: ${reference(c,plan.reference)}.`)}`}</section>`;}
function speech(v,c){const a=c.modelSupported&&c.plan?core.ratioAmounts(c.case,c.plan):null;return [c.case.prompt,recipe(c),fact(c),...c.case.guided,c.plan?`Your bars: ${named(c,c.plan)}. Scoops in every block: ${c.plan.unit??'value not chosen'}. Your reference marker: ${reference(c,c.plan.reference)}.`:'',a?`${c.ingredients.map((i,n)=>`${i.label}: ${c.plan.blocks[n]} times ${c.plan.unit} equals ${a.shares[n]} scoops.`).join(' ')} All bars together: ${a.total} scoops. ${c.plan.reference?`Amount under your marker: ${a.markerAmount} scoops.`:''}`:'Value not chosen'].filter(x=>typeof x==='string').concat(!c.recordReadable?[msg('Unreadable case')]:c.latest?[c.draftStatus==='changed'?'Bars changed since this comparison.':'',`Checked model: ${named(c,c.latest)}, ${c.latest.unit} scoops in every block, marker ${reference(c,c.latest.reference)}.`,...core.ratioFeedback(v.source,c.case,c.latest)]:[msg('No comparison')]).join(' ');}
function task(v,u){const c=core.ratioCaseView(v,u.id);if(!c.case)return p(msg('Unreadable case'));const index=v.source.cases.findIndex(i=>i.id===u.id),allowed=c.modelSupported&&c.draftReadable&&c.supportReadable;return `<h2 id="rb-focus" tabindex="-1">${esc(c.case.title)}</h2><p class="rb-goal">${esc(c.case.prompt)}</p><div class="rb-source"><strong>The ordered recipe</strong>${p(recipe(c))}<strong class="rb-given">${esc(fact(c))}</strong></div>${c.case.guided.length?`<div class="rb-guided"><strong>Guided example</strong><ol>${c.case.guided.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div>`:''}${!c.modelSupported?p(msg('Unknown model')):''}${unsafe(c)?p(msg('Unreadable case')):''}${board(v,c)}${p(msg('Reference reminder'))}${c.draftStatus==='changed'?p(msg('Draft status')):''}${!c.recordReadable?p(msg('Unreadable case')):c.latest?`${checked(v,c,c.latest,c.draftStatus==='changed'?'Bars changed since this comparison':'Your checked model')}<details><summary>A supplied example and a reason to discuss</summary><h3>Supplied fitting example</h3>${p('Here is one model that fits. It is an example, not a description of your bars. Other equal-block models can fit too.')}${p(c.case.explanation)}${p('Tell a grown-up in your own words or point to the blocks. Nothing spoken is recorded or marked.')}${p(c.case.reasonPrompt)}${p(msg('Revision'))}</details>`:p(msg('No comparison'))}<nav class="rb-help">${Object.entries(helperLabels).filter(([k])=>k==='bridge'||allowed&&(k==='clue'||v.helpers[k]&&v.teachingReadable)).map(([k,t])=>button(t,`data-rb-helper="${k}"`)).join('')}${allowed?hearButton(speech(v,c),'Hear')+button('Working together',`data-rb-together aria-pressed="${c.support?.together===true}"`):''}</nav>${p(msg('Together'))}${c.modelSupported&&Object.values(v.helpers).some(h=>!h)?p(msg('Missing helper')):''}${helpers(v,u,c)}<nav class="rb-navigation">${button('Previous invitation',`data-rb-next="-1" ${index===0?'disabled':''}`)}${button('Next invitation',`data-rb-next="1" ${index===v.source.cases.length-1?'disabled':''}`)}</nav><nav class="rb-invitations" aria-label="Choose an invitation"><h3>Choose an invitation</h3>${v.source.cases.map(i=>button(i.title,`data-rb-case="${esc(i.id)}" aria-current="${u.id===i.id?'true':'false'}"`)).join('')}</nav>`;}
const grownup=copy.literals.filter(t=>['These are invented exact','A given whole is shared','Different subdivisions can fit:','The source fact stays fixed.','Existing Sharing Counter,','Only the frozen supplied source,'].some(prefix=>t.startsWith(prefix)));
export function ratioBarsEntry(){return `<aside class="rb-entry"><h3>Equal Blocks</h3>${p('Build equal blocks to share a whole, then try a given share.')}<a href="#studio/mixing/bars">Visit Equal Blocks</a></aside>`;}
export function ratioBarsPage(state,explorerId=''){const v=core.readRatioBars(state),u=visit(state,explorerId);let content;if(v.status==='missing')content=`<h2 id="rb-focus" tabindex="-1">${esc(copy.invitation)}</h2>${p(copy.beforeStart)}${button('Open the blocks','data-rb-start',true)}`;else if(v.status!=='ready')content=`<h2 id="rb-focus" tabindex="-1">Earlier work is retained</h2>${p(msg(v.status==='unsupported'?'Unsupported root':'Unreadable source'))}`;else {if(!v.source.cases.some(c=>c.id===u.id)){u.id=v.source.cases[0].id;u.helper=null;}content=`${sectionBad(v)?p(msg('Unreadable section')):''}${!v.teachingReadable?p('Earlier teaching context cannot be read. You can change bars, but cannot compare or open another worked example here.'):''}${task(v,u)}`;}return `<section data-ratio-bars-view><header class="rb-heading"><a href="#numbers">Number Garden</a><h1>Equal Blocks at the Mixing Table</h1></header><nav class="rb-family" aria-label="Mixing Table tools"><a href="#studio/mixing">Shade pots</a><a href="#studio/mixing/bars" aria-current="page">Equal blocks</a></nav><p id="rb-status" role="status" aria-live="polite" tabindex="-1"></p>${content}${p(copy.notice)}<details><summary>How these blocks work</summary>${p(msg('Notice inside'))}</details><details class="rb-grownup"><summary>Grown-up guide</summary>${grownup.map(p).join('')}${p(msg('Picture-editing note in grown-up help'))}${p(msg('Reset note'))}</details><p>${button('Download our notes','data-rb-download')} <a href="#notes">Grown-up notes</a></p></section>`;}
function observationNotes(v,c,x,label){const overlap=core.ratioHelperOverlap(v,c.case.id,x.teachingBefore);return `<section><h4>${esc(label)}</h4>${supplied(c)}${checked(v,c,x,label)}<ul>${['clue','narration','together'].map((k,n)=>`<li>${['Clue opened','Hear requested','Working together reported'][n]}: ${x.supportBefore[k]?'Recorded before this comparison':'Not recorded before this comparison'}</li>`).join('')}${['whole','share','three'].map((k,n)=>`<li>${['Whole example opened','Share example opened','Three-part example opened'][n]}: ${x.teachingBefore[k]?'Recorded before this comparison':'Not recorded before this comparison'}</li>`).join('')}<li>Feedback available for this comparison: ${x.afterFeedback?'yes':'no'}</li></ul>${overlap.own.map(k=>p(`${{whole:'Whole',share:'Share',three:'Three-part'}[k]} example opened for this invitation’s own recipe and given amount`)+p('The example may supply part or all of a fitting plan; opening does not show which steps were viewed.')+p('Later fits on this invitation are potentially answer-supported; they do not establish fresh new use.')).join('')}${overlap.unknown.length?p('Earlier opened-example details are unavailable; overlap with this invitation is unknown.'):''}</section>`;}
export function ratioBarsNotes(state){const v=core.readRatioBars(state);if(v.status==='missing')return '';return `<details class="panel rb-notes"><summary>Equal Blocks at the Mixing Table</summary>${p(copy.beforeStart)}${v.status==='ready'?`${p(v.source.title)}${p(v.source.origin)}${p(v.source.notice)}${!v.modelSupported?p(msg('Unknown model')):''}${sectionBad(v)?p(msg('Unreadable section')):''}${v.source.cases.map(item=>{const c=core.ratioCaseView(v,item.id);return `<section><h3>${esc(item.title)}</h3>${p(recipe(c))}${p(fact(c))}${supplied(c)}<h4>Ungraded bars</h4>${c.plan?`${p(named(c,c.plan))}${p(`Scoops in every block: ${c.plan.unit??'not chosen'}; Reference marker: ${reference(c,c.plan.reference)}.`)}`:p(msg('Unreadable case'))}${!c.recordReadable?p(msg('Unreadable case')):c.record?`${p(`${c.record.compareCount} ${c.record.compareCount===1?'comparison':'comparisons'}`)}${observationNotes(v,c,c.record.first,'First comparison')}${c.record.latest?observationNotes(v,c,c.record.latest,'Latest retry'):''}`:p('No comparison recorded here')}${c.supportReadable?`<ul>${['clue','narration','together'].map((k,n)=>`<li>${['Clue opened','Hear requested','Working together reported'][n]}: ${c.support[k]?'Recorded here':'Not recorded here'}</li>`).join('')}</ul>`:p(msg('Unreadable case'))}</section>`;}).join('')}${v.teachingReadable?`<ul>${['whole','share','three'].map((k,n)=>`<li>${['Whole example opened','Share example opened','Three-part example opened'][n]}: ${v.root.teaching[k]?'Recorded for this explorer':'Not recorded for this explorer'}</li>`).join('')}</ul>`:p('Earlier teaching context cannot be read. Its original stays in these notes.')}`:p(msg(v.status==='unsupported'?'Unsupported root':'Unreadable source'))}<details><summary>Original saved Equal Blocks data</summary><pre>${esc(json(state.ratioBars))}</pre></details></details>`;}
export function bindRatioBars(state,{notebook=()=>state,explorerId=()=>'',isActive=()=>true,save,render,focus,canExport,download,stopSpeech,stopSound}={}){const host=document.querySelector('[data-ratio-bars-view]');if(!host)return;const u=visit(state,explorerId()),boundExplorer=explorerId(),boundCase=u.id,boundHelper=u.helper,boundStep=u.step,boundSource=json(core.readRatioBars(state).source);let boundRoot=state.ratioBars;const live=el=>el.isConnected&&host.isConnected&&!el.closest('[hidden]')&&el.getClientRects().length>0&&notebook()===state&&explorerId()===boundExplorer&&isActive()&&window.location.hash==='#studio/mixing/bars'&&visits.get(state)===u&&u.id===boundCase&&u.helper===boundHelper&&u.step===boundStep&&state.ratioBars===boundRoot&&json(core.readRatioBars(state).source)===boundSource;
const status=(t,take=false)=>{const box=host.querySelector('#rb-status');if(box){box.textContent=t;if(take)box.focus();}};
const refusal=r=>msg(r.code==='compare-count-cap'?'Count ceiling':r.code==='report-safety'?'Whole-report refusal':'Unreadable case');
const persist=()=>{try{const r=save?.();return r?.enabled===false?msg('Save-off'):r?.ok===false?msg('Storage failure'):'';}catch{return msg('Storage failure');}};
const redraw=(target='#rb-focus',message='',write=false)=>{const note=write?persist():'';stopSpeech?.();stopSound?.();render?.();const next=document.querySelector('[data-ratio-bars-view]');if(!next)return;const box=next.querySelector('#rb-status');if(box)box.textContent=[message,note].filter(Boolean).join(' ');if(focus)focus(target);else next.querySelector(target)?.focus();};
const bind=(selector,fn,eventName='click')=>host.querySelectorAll(selector).forEach(el=>el.addEventListener(eventName,event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}fn(el,event);}));
const mutate=(r,target,message='')=>{if(!r.ok)return status(refusal(r),true);if(r.changed)redraw(target,message,true);return r;};
bind('[data-rb-start]',()=>{const r=core.createRatioBars(state,canExport);if(!r.ok)return status(refusal(r),true);u.id=core.readRatioBars(state).source.cases[0].id;redraw('#rb-focus','',r.changed);});
bind('[data-rb-download]',()=>download?.());
bind('[data-rb-case]',el=>{u.id=el.dataset.rbCase;u.helper=null;redraw();});
bind('[data-rb-next]',el=>{const cases=core.readRatioBars(state).source.cases,index=cases.findIndex(c=>c.id===u.id),next=cases[index+Number(el.dataset.rbNext)];if(next){u.id=next.id;u.helper=null;redraw();}});
bind('[data-rb-adjust]',el=>{const index=Number(el.dataset.index),delta=Number(el.dataset.delta),r=core.adjustRatioBlocks(state,u.id,index,delta,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed){const count=core.ratioCaseView(state,u.id).plan.blocks[index],nextDelta=count===0?1:count===12?-1:delta;redraw(`[data-rb-adjust=${CSS.escape(el.dataset.rbAdjust)}][data-delta="${nextDelta}"]`,msg('Draft status'),true);}});
bind('[data-rb-unit]',el=>mutate(core.setRatioUnit(state,u.id,el.value===''?null:Number(el.value),canExport),'[data-rb-unit]',msg('Draft status')),'change');
bind('[data-rb-reference]',el=>mutate(core.setRatioReference(state,u.id,el.value,canExport),`[data-rb-reference=${CSS.escape(el.value)}]`,msg('Draft status')),'change');
bind('[data-rb-compare]',()=>{const c=core.ratioCaseView(state,u.id),plan=c.plan;const missing=[];if(plan.blocks.every(n=>n===0))missing.push('Add at least one block before comparing.');if(plan.unit===null)missing.push('Choose how many scoops every block stands for.');if(plan.reference===null)missing.push('Place your reference marker before comparing.');if(missing.length)return status(missing.join(' '),true);const r=core.compareRatioBars(state,u.id,canExport);if(!r.ok)return status(refusal(r),true);if(r.changed)redraw('#rb-checked-focus','',true);else {status(msg('No-op'));host.querySelector('#rb-checked-focus')?.focus();}});
bind('[data-rb-together]',()=>mutate(core.noteRatioSupport(state,u.id,'together',canExport),'[data-rb-together]','Working together reported.'));
bind('[data-rb-helper]',el=>{const type=el.dataset.rbHelper;let r=type==='bridge'?{ok:true,changed:false}:type==='clue'?core.noteRatioSupport(state,u.id,'clue',canExport):core.noteRatioTeaching(state,type,canExport);if(!r.ok)return status(refusal(r),true);u.helper=type;u.step=0;redraw('#rb-helper-focus','',r.changed);});
bind('[data-rb-step]',el=>{const h=core.readRatioBars(state).helpers[u.helper];if(!h)return status(msg('Missing helper'),true);u.step=Math.max(0,Math.min(h.steps.length-1,u.step+Number(el.dataset.rbStep)));redraw('#rb-helper-focus');});
bind('[data-rb-close]',()=>{const type=u.helper;u.helper=null;redraw(`[data-rb-helper="${type}"]`);});
bind('[data-rb-return]',(el,e)=>{e.preventDefault();e.stopImmediatePropagation();u.helper=null;redraw('[data-rb-helper="bridge"]');});
host.querySelectorAll('[data-speak]').forEach(el=>el.addEventListener('click',event=>{if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}const r=core.noteRatioSupport(state,u.id,'narration',canExport);if(!r.ok){event.preventDefault();event.stopImmediatePropagation();status(refusal(r),true);return;}if(r.changed){boundRoot=state.ratioBars;const note=persist();if(note)status(note);}},true));
}
